def validate_traces(arr, fields, seen_ids, counters):
    if not isinstance(arr, list):
        die("E_SCHEMA")
    traces = []
    for tr in arr:
        if not isinstance(tr, dict):
            die("E_SCHEMA")
        if set(tr.keys()) != {"id", "source", "rows"}:
            die("E_SCHEMA")
        tid = tr["id"]
        src = tr["source"]
        rows = tr["rows"]
        if not is_str(tid) or RE_TID.fullmatch(tid) is None:
            die("E_SCHEMA")
        if not is_str(src) or RE_TID.fullmatch(src) is None:
            die("E_SCHEMA")
        if tid in seen_ids:
            die("E_SCHEMA")
        seen_ids.add(tid)
        if not isinstance(rows, list):
            die("E_SCHEMA")
        counters["traces"] += 1
        if counters["traces"] > MAX_TRACES:
            die("E_SCHEMA")
        parsed_rows = []
        seen_t = set()
        for row in rows:
            if not isinstance(row, dict):
                die("E_SCHEMA")
            if set(row.keys()) != {"t", "values"}:
                die("E_SCHEMA")
            tval = row["t"]
            if not is_i32(tval):
                die("E_SCHEMA")
            if tval in seen_t:
                die("E_SCHEMA")
            seen_t.add(tval)
            parsed_rows.append((tval, validate_row_values(row["values"], fields)))
            counters["rows"] += 1
            if counters["rows"] > MAX_ROWS:
                die("E_SCHEMA")
        parsed_rows.sort(key=lambda item: item[0])
        traces.append({"id": tid, "source": src, "rows": parsed_rows})
    return traces


def build_contexts(traces, K):
    contexts = []
    for tr in traces:
        rows = tr["rows"]
        n = len(rows)
        if n < K:
            continue
        vals = [r[1] for r in rows]
        times = [r[0] for r in rows]
        tid = tr["id"]
        src = tr["source"]
        for i in range(n - K + 1):
            contexts.append((tuple(vals[i:i + K]), tid, src, times[i + K - 1]))
    return contexts


